using Microsoft.AspNetCore.HttpOverrides;

var builder = WebApplication.CreateBuilder(args);

// FIX (Breaking Change 1 — DI ValidateOnBuild/ValidateScopes):
// .NET 9 enables ValidateScopes in development by default.
// A singleton (ICacheService) that resolves a scoped service (IUserService)
// is a captive-dependency bug that now throws at startup.
// Fix: register ICacheService as scoped so its lifetime matches IUserService.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// FIX (Breaking Change 2 — HttpClientFactory uses SocketsHttpHandler):
// .NET 9 changed the default primary handler from HttpClientHandler to
// SocketsHttpHandler. The cast on line 8 would throw InvalidCastException.
// Fix: use ConfigurePrimaryHttpMessageHandler to set the handler directly.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() =>
        new SocketsHttpHandler { UseCookies = false });

// FIX (Breaking Change 3 — Forwarded Headers ignores unknown proxies):
// .NET 9 now silently drops X-Forwarded-* headers from proxies not in
// KnownProxies/KnownNetworks. Configure your trusted proxy address here.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: replace with your actual reverse-proxy address(es)
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});

// FIX (Breaking Change 4 — HttpClientFactory header redaction):
// .NET 9 redacts all HTTP header values in Trace-level logs by default.
// Allowlist the specific non-sensitive headers you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(name =>
        name != "X-Request-Id"
        && name != "X-Correlation-Id"
        && name != "Accept"
        && name != "Content-Type"));

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

// Stub types (replace with real implementations)
public interface IUserService { }
public class UserService : IUserService { }
public interface ICacheService { }
public class CacheService(IUserService userService) : ICacheService { }

